<section class="page-heading detail-heading">
    <div><a class="breadcrumb" href="/documents"><?= ui_icon('arrow-left') ?> Kembali</a><span class="eyebrow">BATCH DOKUMEN</span><h1><?= e($batch['label']?:'Batch #'.$batch['id']) ?></h1><p><?= count($documents) ?> dokumen menggunakan satu alur batch.</p></div>
    <div class="heading-actions">
        <?php if(!empty($exactDocxAvailable)): ?><a class="btn btn-primary" href="/document-batches/<?= (int)$batch['id'] ?>/download-docx"><?= ui_icon('download') ?> Unduh Semua DOCX Presisi</a><?php endif; ?>
        <a class="btn btn-secondary" target="_blank" href="/document-batches/<?= (int)$batch['id'] ?>/print"><?= ui_icon('printer') ?> Preview Cetak Semua</a>
    </div>
</section>
<?php if(!empty($exactDocxAvailable)): ?><section class="precision-banner"><span class="precision-banner-icon"><?= ui_icon('layers') ?></span><div><strong>Batch layout asli</strong><p>Setiap file DOCX di dalam ZIP dibuat dari template Word sumber yang sama, lalu data masing-masing surat diisikan tanpa membangun ulang layout.</p></div></section><?php endif; ?>
<?php $pending=count(array_filter($documents,fn($d)=>$d['tte_status']==='PENDING'));$signed=count(array_filter($documents,fn($d)=>$d['tte_status']==='SIGNED'));$draft=count($documents)-$pending-$signed; ?>
<?php $pendingSignerGroups=[]; foreach($documents as $doc){ if($doc['tte_status']==='PENDING') $pendingSignerGroups[(int)$doc['signer_id']]=$doc['signer_name']; } ?>
<section class="panel signature-workflow batch-signature-workflow"><div><span class="eyebrow">TANDA TANGAN BATCH</span><h2><?= $signed ?> ditandatangani · <?= $pending ?> menunggu · <?= $draft ?> belum diajukan</h2><p>Jika satu penanda tangan dipakai, cukup satu passkey. Jika surat memakai beberapa penanda tangan, masukkan passkey masing-masing.</p></div><div class="signature-actions"><?php if($pending===0&&$signed<count($documents)):?><form method="post" action="/document-batches/<?= (int)$batch['id'] ?>/submit"><?= csrf_field() ?><button class="btn btn-primary" type="submit">Ajukan Semua</button></form><?php endif;?><?php if($pending>0&&\App\Core\Auth::isAdmin()):?><form method="post" action="/document-batches/<?= (int)$batch['id'] ?>/sign" class="batch-multi-sign-form"><?= csrf_field() ?><?php foreach($pendingSignerGroups as $signerId=>$signerName): ?><label class="field"><span>Passkey · <?= e($signerName) ?></span><input type="password" name="passkeys[<?= (int)$signerId ?>]" placeholder="Passkey penanda tangan" required></label><?php endforeach; ?><button class="btn btn-primary" type="submit"><?= ui_icon('signature') ?> Tanda Tangani Semua</button></form><form method="post" action="/document-batches/<?= (int)$batch['id'] ?>/reject" class="inline-sign-form"><?= csrf_field() ?><input name="reason" placeholder="Alasan penolakan"><button class="btn btn-danger" type="submit">Tolak Semua</button></form><?php endif;?></div></section>
<section class="batch-preview-grid"><?php foreach($documents as $i=>$doc):?><a class="panel batch-preview-card" href="/documents/<?= (int)$doc['id'] ?>"><span class="batch-index"><?= $i+1 ?></span><div><strong><?= e($doc['letter_number']) ?></strong><p><?= e($doc['subject']) ?></p><small><?= e($doc['recipient']) ?> · <?= e($doc['signer_name']) ?></small><span class="mini-status <?= $doc['tte_status']==='SIGNED'?'ok':($doc['tte_status']==='PENDING'?'warn':'muted') ?>"><?= $doc['tte_status']==='SIGNED'?'Ditandatangani':($doc['tte_status']==='PENDING'?'Menunggu':'Draft') ?></span></div><?= ui_icon('arrow-right') ?></a><?php endforeach;?></section>
